import { CanvasRoot } from "@/components/bevelui/canvas";
import type { CanvasNode } from "@/components/bevelui/canvas";

const initialNodes: CanvasNode[] = [
  { id: "1", x: 40, y: 40, width: 180, height: 100, data: { label: "Start" } },
  { id: "2", x: 320, y: 160, width: 180, height: 100, data: { label: "Process" } },
];

export default function BoardPage() {
  return (
    <div className="h-[600px] w-full">
      <CanvasRoot
        defaultNodes={initialNodes}
        config={{ gridSnap: 8 }}
        renderNode={(node, isSelected) => (
          <div
            className={`flex h-full w-full items-center justify-center rounded-lg border bg-card text-sm ${
              isSelected ? "border-primary" : "border-border"
            }`}
          >
            {(node.data as { label: string })?.label}
          </div>
        )}
      />
    </div>
  );
}

const { addNode, removeNode, updateNode, moveNodes } = useCanvas();

addNode({ id: crypto.randomUUID(), x: 100, y: 100, width: 160, height: 90 });

updateNode("1", { width: 220 });

moveNodes(["1", "2"], 24, 0); // nudge two nodes right by 24px

removeNode("2");

const [nodes, setNodes] = React.useState(initialNodes);

<CanvasRoot
  defaultNodes={nodes}
  onChange={(updated) => setNodes(updated)}
  renderNode={(node) => <NodeCard node={node} />}
/>

const { selection, select, clearSelection } = useCanvas();

select(["1", "2"], "add");   // add to current selection
select(["3"], "toggle");     // toggle membership
select(["1"]);               // replace selection
clearSelection();

const { zoomTo, zoomToFit, centerOn, viewport } = useCanvas();

zoomToFit();          // frames all nodes with default padding
zoomToFit(80);        // custom padding in px
centerOn("node-3");   // centers the viewport on a specific node
zoomTo(1);            // reset to 100%

console.log(viewport); // { x, y, zoom }

import {
  CanvasRoot, CanvasViewport, useCanvas,
} from "@/components/bevelui/canvas";

function ZoomControls() {
  const { viewport, zoomTo, zoomToFit } = useCanvas();
  return (
    <div className="absolute bottom-3 right-3 flex items-center gap-2 rounded-lg border border-border bg-card/90 px-2 py-1 text-xs">
      <button onClick={() => zoomTo(viewport.zoom * 0.9)}>-</button>
      <span>{Math.round(viewport.zoom * 100)}%</span>
      <button onClick={() => zoomTo(viewport.zoom * 1.1)}>+</button>
      <button onClick={() => zoomToFit()}>Fit</button>
    </div>
  );
}

export function Board() {
  return (
    <CanvasRoot defaultNodes={nodes} className="relative h-full w-full">
      <CanvasViewport renderNode={(node) => <NodeCard node={node} />} />
      <ZoomControls />
    </CanvasRoot>
  );
}
